pm.test('Khong co truong nao ngoai hop dong API', function () {
    var allowed = ['id', 'name', 'email', 'role', 'shipping_address', 'phone'];
    var extra = Object.keys(J()).filter(function (k) { return allowed.indexOf(k) === -1; });
    pm.expect(extra, 'truong thua bi ro ri: ' + extra.join(', ')).to.be.an('array').that.is.empty;
});
